import { createContext, useContext, useState, type FormEvent, type ReactNode } from 'react'
import { BrowserRouter, Link, Navigate, Outlet, Route, Routes, useLocation, useNavigate, useParams } from 'react-router-dom'
import { Activity, ArrowDownToLine, ArrowLeft, ArrowRight, Bell, CalendarClock, Check, ChevronDown, ChevronLeft, ChevronRight, CircleHelp, Clock3, Command, ContactRound, DollarSign, Ellipsis, FileBarChart, Filter, Kanban, LayoutDashboard, ListFilter, LogOut, Mail, Menu, MessageSquareText, MoreHorizontal, Plus, Search, Settings, ShieldCheck, Sparkles, Target, Users, X } from 'lucide-react'
import { Area, AreaChart, CartesianGrid, Cell, Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts'
import { dashboardMetrics, initialActivities, initialCustomers, initialFollowUps, initialLeads, initialOpportunities, initialUsers, type ActivityItem, type Customer, type FollowUp, type Lead, type Opportunity } from './data/mockData'
import './App.css'

type CRMState = { customers: Customer[]; leads: Lead[]; opportunities: Opportunity[]; followUps: FollowUp[]; activities: ActivityItem[]; users: typeof initialUsers; addCustomer: (item: Customer) => void; updateCustomer: (id: string, item: Customer) => void; addLead: (item: Lead) => void; updateLead: (id: string, item: Lead) => void; addOpportunity: (item: Opportunity) => void; updateOpportunity: (id: string, stage: string) => void; addFollowUp: (item: FollowUp) => void; addActivity: (item: ActivityItem) => void; completeFollowUp: (id: string) => void; convertLead: (id: string) => void }
const CRMContext = createContext<CRMState | null>(null)
function useCRM() { const value = useContext(CRMContext); if (!value) throw new Error('CRM context is unavailable'); return value }
function nextRecordId(prefix: string) { return `${prefix}-${Date.now().toString().slice(-5)}` }
function todayISO() { return new Date().toISOString().slice(0, 10) }

function CRMProvider({ children }: { children: ReactNode }) {
  const [customers, setCustomers] = useState(initialCustomers)
  const [leads, setLeads] = useState(initialLeads)
  const [opportunities, setOpportunities] = useState(initialOpportunities)
  const [followUps, setFollowUps] = useState(initialFollowUps)
  const [activities, setActivities] = useState(initialActivities)
  const addCustomer = (item: Customer) => setCustomers((items) => [item, ...items])
  const updateCustomer = (id: string, item: Customer) => setCustomers((items) => items.map((current) => current.id === id ? item : current))
  const addLead = (item: Lead) => setLeads((items) => [item, ...items])
  const updateLead = (id: string, item: Lead) => setLeads((items) => items.map((current) => current.id === id ? item : current))
  const addOpportunity = (item: Opportunity) => setOpportunities((items) => [item, ...items])
  const updateOpportunity = (id: string, stage: string) => setOpportunities((items) => items.map((item) => item.id === id ? { ...item, stage, probability: stage === 'Closed Won' ? 100 : stage === 'Closed Lost' ? 0 : item.probability } : item))
  const addFollowUp = (item: FollowUp) => setFollowUps((items) => [item, ...items])
  const addActivity = (item: ActivityItem) => setActivities((items) => [item, ...items])
  const completeFollowUp = (id: string) => setFollowUps((items) => items.map((item) => item.id === id ? { ...item, status: 'Completed' } : item))
  const convertLead = (id: string) => {
    const lead = leads.find((item) => item.id === id)
    if (!lead || lead.status === 'Converted') return
    setCustomers((items) => [{ id: `CUS-${Date.now().toString().slice(-5)}`, name: lead.name, company: lead.company, email: lead.email, phone: lead.phone, status: 'Active', owner: lead.owner, city: 'Bengaluru', created: new Date().toISOString().slice(0, 10) }, ...items])
    setLeads((items) => items.map((item) => item.id === id ? { ...item, status: 'Converted' } : item))
  }
  return <CRMContext.Provider value={{ customers, leads, opportunities, followUps, activities, users: initialUsers, addCustomer, updateCustomer, addLead, updateLead, addOpportunity, updateOpportunity, addFollowUp, addActivity, completeFollowUp, convertLead }}>{children}</CRMContext.Provider>
}

const navigation = [
  { group: 'WORKSPACE', items: [{ to: '/dashboard', label: 'Dashboard', icon: LayoutDashboard }] },
  { group: 'RELATIONSHIPS', items: [{ to: '/customers', label: 'Customers', icon: ContactRound }, { to: '/leads', label: 'Leads', icon: Users }, { to: '/opportunities', label: 'Opportunities', icon: Target }, { to: '/followups', label: 'Follow-ups', icon: CalendarClock }, { to: '/activities', label: 'Activities', icon: Activity }] },
  { group: 'INSIGHTS', items: [{ to: '/reports', label: 'Reports', icon: FileBarChart }] },
  { group: 'ADMINISTRATION', items: [{ to: '/users', label: 'Users', icon: Users }, { to: '/audit-logs', label: 'Audit logs', icon: ShieldCheck }] },
]
const titles: Record<string, string> = { '/dashboard': 'Dashboard', '/customers': 'Customers', '/leads': 'Leads', '/opportunities': 'Opportunities', '/followups': 'Follow-ups', '/activities': 'Activities', '/reports': 'Reports', '/users': 'Users', '/audit-logs': 'Audit logs', '/settings': 'Settings' }

export default function CRMApp() {
  return <CRMProvider><BrowserRouter><Routes>
    <Route path="/login" element={<AuthPage mode="login" />} /><Route path="/register" element={<AuthPage mode="register" />} />
    <Route element={<Shell />}><Route index element={<Navigate to="/dashboard" replace />} /><Route path="dashboard" element={<Dashboard />} />
      <Route path="customers" element={<CustomersPage />} /><Route path="customers/new" element={<RecordForm kind="customer" />} /><Route path="customers/:id/edit" element={<RecordForm kind="customer" />} /><Route path="customers/:id" element={<RecordDetails kind="customer" />} />
      <Route path="leads" element={<LeadsPage />} /><Route path="leads/new" element={<RecordForm kind="lead" />} /><Route path="leads/:id/edit" element={<RecordForm kind="lead" />} /><Route path="leads/:id" element={<RecordDetails kind="lead" />} />
      <Route path="opportunities" element={<OpportunitiesPage />} /><Route path="opportunities/new" element={<RecordForm kind="opportunity" />} /><Route path="opportunities/:id" element={<RecordDetails kind="opportunity" />} /><Route path="followups" element={<FollowUpsPage />} /><Route path="activities" element={<ActivitiesPage />} /><Route path="reports" element={<ReportsPage />} /><Route path="users" element={<UsersPage />} /><Route path="audit-logs" element={<AuditPage />} /><Route path="settings" element={<SettingsPage />} /><Route path="*" element={<NotFound />} />
    </Route>
  </Routes></BrowserRouter></CRMProvider>
}

function Shell() {
  const location = useLocation(); const navigate = useNavigate(); const [collapsed, setCollapsed] = useState(false); const [drawer, setDrawer] = useState(false); const [profileOpen, setProfileOpen] = useState(false); const [noticeOpen, setNoticeOpen] = useState(false); const [search, setSearch] = useState('')
  const title = Object.entries(titles).find(([path]) => location.pathname.startsWith(path))?.[1] ?? (location.pathname.includes('/new') ? 'New record' : 'Record overview')
  return <div className={`app-shell ${collapsed ? 'sidebar-collapsed' : ''}`}>
    {drawer && <button className="drawer-scrim" aria-label="Close navigation" onClick={() => setDrawer(false)} />}
    <aside className={`sidebar ${drawer ? 'drawer-open' : ''}`}>
      <Link className="brand" to="/dashboard" onClick={() => setDrawer(false)}><span className="brand-mark"><Command size={18} /></span><span className="brand-name">acxiom<span>crm</span></span></Link>
      <div className="workspace-switch"><span className="workspace-icon">A</span><span className="workspace-text"><strong>Acxiom Group</strong><small>Sales workspace</small></span><ChevronDown size={15} /></div>
      <nav className="side-nav" aria-label="Main navigation">{navigation.map((group) => <section key={group.group} className="nav-group"><div className="nav-heading">{group.group}</div>{group.items.map(({ to, label, icon: Icon }) => <Link key={to} to={to} onClick={() => setDrawer(false)} className={`nav-link ${location.pathname.startsWith(to) ? 'active' : ''}`} title={label}><Icon size={17} strokeWidth={1.8} /><span>{label}</span>{label === 'Follow-ups' && <i className="nav-count">4</i>}</Link>)}</section>)}</nav>
      <div className="sidebar-bottom"><Link to="/settings" className={`nav-link ${location.pathname.startsWith('/settings') ? 'active' : ''}`}><Settings size={17} /><span>Settings</span></Link><button className="nav-link"><CircleHelp size={17} /><span>Help center</span></button><div className="sidebar-user"><span className="avatar avatar-green">SK</span><span className="sidebar-user-copy"><strong>Sandya Kandi</strong><small>Sales Executive</small></span><MoreHorizontal size={17} /></div></div>
    </aside>
    <div className="main-column"><header className="topbar"><div className="topbar-left"><button className="icon-button mobile-menu" aria-label="Open menu" onClick={() => setDrawer(true)}><Menu size={19} /></button><button className="icon-button collapse-toggle" aria-label="Toggle sidebar" onClick={() => setCollapsed(!collapsed)}><ListFilter size={18} /></button><div className="breadcrumb"><span>Workspace</span><ChevronRight size={14} /><strong>{title}</strong></div></div><div className="topbar-actions"><label className="global-search"><Search size={16} /><input placeholder="Search anything..." value={search} onChange={(event) => setSearch(event.target.value)} onKeyDown={(event) => event.key === 'Enter' && navigate(`/customers?search=${encodeURIComponent(search)}`)} /><kbd>⌘ K</kbd></label><div className="topbar-divider" /><div className="dropdown-anchor"><button className="icon-button notification-button" aria-label="Notifications" onClick={() => setNoticeOpen(!noticeOpen)}><Bell size={18} /><i /></button>{noticeOpen && <div className="popover notice-popover"><strong>You’re all caught up</strong><span>No new notifications.</span></div>}</div><div className="dropdown-anchor"><button className="profile-trigger" onClick={() => setProfileOpen(!profileOpen)}><span className="avatar avatar-green">SK</span><span className="profile-copy"><strong>Sandya Kandi</strong><small>Sales Executive</small></span><ChevronDown size={15} /></button>{profileOpen && <div className="popover profile-popover"><Link to="/settings"><Settings size={15} />Profile &amp; settings</Link><Link to="/login"><LogOut size={15} />Sign out</Link></div>}</div></div></header><main className="main-content"><Outlet /></main><footer className="app-footer"><span>AcxiomCRM <span className="footer-dot">·</span> Customer Relationship Management</span><span>© 2025 Acxiom Group</span></footer></div>
  </div>
}

function PageHeader({ eyebrow, title, description, actions }: { eyebrow?: string; title: string; description?: string; actions?: ReactNode }) { return <div className="page-heading"><div>{eyebrow && <div className="eyebrow">{eyebrow}</div>}<h1>{title}</h1>{description && <p>{description}</p>}</div>{actions && <div className="page-actions">{actions}</div>}</div> }
function Button({ children, onClick, variant = 'primary', type = 'button', icon, className = '' }: { children: ReactNode; onClick?: () => void; variant?: 'primary' | 'secondary' | 'quiet' | 'danger'; type?: 'button' | 'submit'; icon?: ReactNode; className?: string }) { return <button type={type} onClick={onClick} className={`button button-${variant} ${className}`}>{icon}{children}</button> }
function Avatar({ name, small = false }: { name: string; small?: boolean }) { return <span className={`avatar ${small ? 'avatar-small' : ''} avatar-${name.charCodeAt(0) % 5}`}>{name.split(' ').map((part) => part[0]).join('').slice(0, 2).toUpperCase()}</span> }
function StatusBadge({ status }: { status: string }) { return <span className={`status-badge status-${status.toLowerCase().replaceAll(' ', '-')}`}><i />{status}</span> }
function SearchInput({ value, onChange, placeholder = 'Search records...' }: { value: string; onChange: (value: string) => void; placeholder?: string }) { return <label className="table-search"><Search size={16} /><input value={value} onChange={(event) => onChange(event.target.value)} placeholder={placeholder} />{value && <button type="button" aria-label="Clear search" onClick={() => onChange('')}><X size={14} /></button>}</label> }
function TableWrap({ children }: { children: ReactNode }) { return <div className="table-scroll"><table className="data-table">{children}</table></div> }
function EmptyState({ title, text }: { title: string; text: string }) { return <div className="empty-state"><span className="empty-icon"><Sparkles size={19} /></span><strong>{title}</strong><p>{text}</p></div> }
function Toast({ message, onClose }: { message: string; onClose: () => void }) { if (!message) return null; return <div className="toast"><span><Check size={15} /></span>{message}<button onClick={onClose} aria-label="Dismiss notification"><X size={15} /></button></div> }

function Dashboard() {
  const { leads, followUps, activities } = useCRM()
  const metricIcons = { customers: ContactRound, leads: Users, 'open-leads': Users, opportunities: Target, pipeline: DollarSign, won: Check, lost: Target, 'follow-ups': CalendarClock }
  const sales = [{ month: 'May', won: 18, target: 20 }, { month: 'Jun', won: 24, target: 22 }, { month: 'Jul', won: 19, target: 25 }, { month: 'Aug', won: 31, target: 26 }, { month: 'Sep', won: 27, target: 30 }, { month: 'Oct', won: 38, target: 32 }]
  const mix = [{ name: 'New', value: leads.filter((item) => item.status === 'New').length, color: '#52b7a7' }, { name: 'Contacted', value: 3, color: '#7b9ded' }, { name: 'Qualified', value: leads.filter((item) => item.status === 'Qualified').length, color: '#e6b65a' }, { name: 'Converted', value: leads.filter((item) => item.status === 'Converted').length, color: '#bc8de4' }, { name: 'Other', value: 2, color: '#d9e1df' }]
  return <><PageHeader eyebrow="THURSDAY, OCTOBER 8, 2026" title="Good morning, Sandya" description="Here’s what’s happening across your relationships today." actions={<Button variant="secondary" icon={<ArrowDownToLine size={16} />}>Export</Button>} />
    <div className="stat-grid">{dashboardMetrics.map(({ label, value, delta, icon, tone }) => { const Icon = metricIcons[icon as keyof typeof metricIcons]; return <article className="stat-card" key={label}><div className={`stat-icon ${tone}`}><Icon size={18} /></div><span className="stat-label">{label}</span><div className="stat-value">{value}</div><div className="stat-foot"><span className="positive">↗ {delta}</span><span>{delta === 'Today' ? 'needs attention' : 'vs. last month'}</span></div></article> })}</div>
    <div className="dashboard-grid charts-row"><section className="panel sales-panel"><div className="panel-heading"><div><h2>Revenue performance</h2><p>Closed-won revenue over time</p></div><button className="select-like">Last 6 months <ChevronDown size={14} /></button></div><div className="chart-legend"><span><i className="legend-teal" />Revenue</span><span><i className="legend-gray" />Target</span></div><div className="sales-chart"><ResponsiveContainer width="100%" height="100%"><AreaChart data={sales} margin={{ top: 8, right: 7, left: -24, bottom: 0 }}><defs><linearGradient id="revenueFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#42a99c" stopOpacity={0.2} /><stop offset="92%" stopColor="#42a99c" stopOpacity={0} /></linearGradient></defs><CartesianGrid stroke="#edf1ef" vertical={false} /><XAxis dataKey="month" axisLine={false} tickLine={false} tick={{ fill: '#929c99', fontSize: 11 }} dy={9} /><YAxis axisLine={false} tickLine={false} tick={{ fill: '#929c99', fontSize: 11 }} tickFormatter={(value) => `₹${value}k`} /><Tooltip /><Area type="monotone" dataKey="target" stroke="#bfc9c5" strokeDasharray="4 4" fill="none" strokeWidth={1.5} /><Area type="monotone" dataKey="won" stroke="#2d9185" fill="url(#revenueFill)" strokeWidth={2.5} /></AreaChart></ResponsiveContainer></div></section>
      <section className="panel leads-panel"><div className="panel-heading"><div><h2>Lead distribution</h2><p>By current status</p></div><button className="icon-button" aria-label="More options"><Ellipsis size={19} /></button></div><div className="donut-wrap"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={mix} dataKey="value" nameKey="name" innerRadius={58} outerRadius={78} paddingAngle={3} stroke="none">{mix.map((entry) => <Cell key={entry.name} fill={entry.color} />)}</Pie><Tooltip /></PieChart></ResponsiveContainer><div className="donut-center"><strong>{leads.length}</strong><span>Total leads</span></div></div><div className="lead-legend">{mix.slice(0, 4).map((item) => <div key={item.name}><span><i style={{ background: item.color }} />{item.name}</span><strong>{item.value}</strong></div>)}</div></section></div>
    <div className="dashboard-grid lower-row"><section className="panel activity-panel"><div className="panel-heading"><div><h2>Recent activity</h2><p>Latest updates from your team</p></div><Link className="text-link" to="/activities">View all <ArrowRight size={14} /></Link></div><div className="activity-list">{activities.slice(0, 5).map((item) => <div className="activity-item" key={item.id}><span className={`activity-symbol activity-${item.type.toLowerCase()}`}>{item.type === 'Email' ? <Mail size={15} /> : item.type === 'Meeting' ? <Users size={15} /> : item.type === 'Note' ? <MessageSquareText size={15} /> : '↗'}</span><div className="activity-copy"><strong>{item.subject}</strong><span>{item.description}</span></div><div className="activity-meta"><Avatar name={item.user} small /><span>{item.time}</span></div></div>)}</div></section><section className="panel followup-panel"><div className="panel-heading"><div><h2>Upcoming follow-ups</h2><p>Stay ahead of your conversations</p></div><Link className="text-link" to="/followups">View all <ArrowRight size={14} /></Link></div><div className="followup-list">{followUps.filter((item) => item.status !== 'Completed').slice(0, 4).map((item) => <div className="followup-item" key={item.id}><div className="followup-date"><strong>{item.date.slice(-2)}</strong><span>{item.date.slice(5, 7) === '10' ? 'OCT' : 'SEP'}</span></div><div className="followup-copy"><strong>{item.subject}</strong><span>{item.related} · {item.type}</span></div><span className={`followup-time ${item.status === 'Overdue' ? 'overdue' : ''}`}><Clock3 size={13} />{item.time}</span></div>)}</div></section></div>
    <div className="dashboard-bottom-note"><span><Check size={15} />You’re making great progress</span><span>{followUps.filter((item) => item.status === 'Completed').length} follow-ups completed this week</span></div>
  </>
}

function CustomersPage() {
  const { customers } = useCRM(); const [search, setSearch] = useState(new URLSearchParams(window.location.search).get('search') ?? ''); const [status, setStatus] = useState('All statuses')
  const shown = customers.filter((item) => `${item.name} ${item.company} ${item.email} ${item.city}`.toLowerCase().includes(search.toLowerCase()) && (status === 'All statuses' || item.status === status))
  return <><PageHeader title="Customers" description="Manage and grow your customer relationships." actions={<><Button variant="secondary" icon={<ArrowDownToLine size={16} />}>Export</Button><Link className="button button-primary" to="/customers/new"><Plus size={16} />Add customer</Link></>} /><section className="panel table-panel"><div className="table-toolbar"><SearchInput value={search} onChange={setSearch} placeholder="Search customers..." /><select className="filter-select" value={status} onChange={(event) => setStatus(event.target.value)}><option>All statuses</option><option>Active</option><option>Prospect</option><option>Inactive</option></select><button className="button button-secondary filter-button"><Filter size={15} />Filters</button><span className="toolbar-spacer" /><span className="result-count">{shown.length} customers</span></div>{shown.length ? <TableWrap><thead><tr><th>Customer</th><th>Company</th><th>Email</th><th>Phone</th><th>Status</th><th>Assigned to</th><th>Created</th><th /></tr></thead><tbody>{shown.map((item) => <tr key={item.id}><td><Link className="person-cell" to={`/customers/${item.id}`}><Avatar name={item.name} small /><strong>{item.name}</strong></Link></td><td>{item.company}</td><td>{item.email}</td><td>{item.phone}</td><td><StatusBadge status={item.status} /></td><td><span className="assigned-cell"><Avatar name={item.owner} small />{item.owner}</span></td><td>{item.created}</td><td><Link className="row-action" to={`/customers/${item.id}`} aria-label={`View ${item.name}`}><ArrowRight size={16} /></Link></td></tr>)}</tbody></TableWrap> : <EmptyState title="No customers found" text="Try adjusting your search or filters." />}<Pagination count={shown.length} label="customers" /></section></>
}
function LeadsPage() {
  const { leads } = useCRM(); const [search, setSearch] = useState(''); const [status, setStatus] = useState('All statuses'); const shown = leads.filter((item) => `${item.name} ${item.company} ${item.source} ${item.owner}`.toLowerCase().includes(search.toLowerCase()) && (status === 'All statuses' || item.status === status))
  return <><PageHeader title="Leads" description="Qualify prospects and build your pipeline." actions={<><Button variant="secondary" icon={<ArrowDownToLine size={16} />}>Export</Button><Link className="button button-primary" to="/leads/new"><Plus size={16} />Add lead</Link></>} /><section className="panel table-panel"><div className="table-toolbar"><SearchInput value={search} onChange={setSearch} placeholder="Search leads..." /><select className="filter-select" value={status} onChange={(event) => setStatus(event.target.value)}><option>All statuses</option>{['New', 'Contacted', 'Qualified', 'Unqualified', 'Converted', 'Lost'].map((item) => <option key={item}>{item}</option>)}</select><button className="button button-secondary filter-button"><Filter size={15} />Filters</button><span className="toolbar-spacer" /><span className="result-count">{shown.length} leads</span></div>{shown.length ? <TableWrap><thead><tr><th>Lead</th><th>Company</th><th>Source</th><th>Status</th><th>Rating</th><th>Assigned to</th><th>Created</th><th /></tr></thead><tbody>{shown.map((item) => <tr key={item.id}><td><Link className="person-cell" to={`/leads/${item.id}`}><Avatar name={item.name} small /><strong>{item.name}</strong></Link></td><td>{item.company}</td><td>{item.source}</td><td><StatusBadge status={item.status} /></td><td><span className={`rating rating-${item.rating.toLowerCase()}`}><i />{item.rating}</span></td><td><span className="assigned-cell"><Avatar name={item.owner} small />{item.owner}</span></td><td>{item.created}</td><td><Link className="row-action" to={`/leads/${item.id}`} aria-label={`View ${item.name}`}><ArrowRight size={16} /></Link></td></tr>)}</tbody></TableWrap> : <EmptyState title="No leads found" text="Try another search or add a new lead." />}<Pagination count={shown.length} label="leads" /></section></>
}
function Pagination({ count, label }: { count: number; label: string }) { return <div className="pagination"><span>Showing <strong>{count ? 1 : 0}–{count}</strong> of <strong>{count}</strong> {label}</span><div><button className="page-control" disabled><ChevronLeft size={15} />Previous</button><button className="page-number active">1</button><button className="page-control" disabled>Next<ChevronRight size={15} /></button></div></div> }

function RecordForm({ kind }: { kind: 'customer' | 'lead' | 'opportunity' }) {
  const { addCustomer, updateCustomer, addLead, updateLead, addOpportunity, customers, leads } = useCRM(); const navigate = useNavigate(); const [error, setError] = useState(''); const isCustomer = kind === 'customer'; const id = useParams().id
  const existingCustomer = kind === 'customer' ? customers.find((item) => item.id === id) : undefined
  const existingLead = kind === 'lead' ? leads.find((item) => item.id === id) : undefined
  const existing = existingCustomer ?? existingLead
  const editing = Boolean(id)
  function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const form = new FormData(event.currentTarget)
    if (kind === 'opportunity') { addOpportunity({ id: nextRecordId('OPP'), name: String(form.get('name')), customer: String(form.get('customer')), amount: Number(form.get('amount')), stage: String(form.get('stage')), probability: Number(form.get('probability')), closeDate: String(form.get('closeDate')), owner: String(form.get('owner')) }); navigate('/opportunities'); return }
    const first = String(form.get('first') || '').trim(); const last = String(form.get('last') || '').trim(); const email = String(form.get('email') || ''); if (!first || !last || !/^\S+@\S+\.\S+$/.test(email)) { setError('Add a first name, last name, and valid email address.'); return } const name = `${first} ${last}`; const today = todayISO()
    if (isCustomer) { const item = { id: id ?? nextRecordId('CUS'), name, company: String(form.get('company') || 'Independent'), email, phone: String(form.get('phone') || '—'), status: String(form.get('status') || 'Active'), owner: String(form.get('owner') || 'Sandya Kandi'), city: String(form.get('city') || 'Bengaluru'), created: existing?.created ?? today }; if (editing) updateCustomer(item.id, item); else addCustomer(item) }
    else { const item = { id: id ?? nextRecordId('LEA'), name, company: String(form.get('company') || 'Independent'), email, phone: String(form.get('phone') || '—'), source: String(form.get('source') || 'Website'), status: String(form.get('status') || 'New'), rating: String(form.get('rating') || 'Warm'), owner: String(form.get('owner') || 'Sandya Kandi'), created: existing?.created ?? today }; if (editing) updateLead(item.id, item); else addLead(item) }
    navigate(isCustomer ? '/customers' : '/leads')
  }
  if (kind === 'opportunity') return <><PageHeader eyebrow="OPPORTUNITY MANAGEMENT" title="Add opportunity" description="Capture the next potential customer win." actions={<Link to="/opportunities" className="button button-quiet"><ArrowLeft size={15} />Back</Link>} /><form className="form-layout" onSubmit={submit}><section className="panel form-panel"><div className="form-section-title"><span>01</span><div><h2>Opportunity details</h2><p>Deal value, stage, and expected close date.</p></div></div><div className="form-grid"><Field label="Opportunity name" name="name" required placeholder="e.g. Enterprise rollout" /><Field label="Customer" name="customer" required placeholder="Customer or company" /><Field label="Amount (₹)" name="amount" type="number" required placeholder="500000" /><SelectField label="Stage" name="stage" options={['Prospecting', 'Qualification', 'Proposal', 'Negotiation', 'Closed Won', 'Closed Lost']} /><Field label="Probability (%)" name="probability" type="number" required placeholder="25" /><Field label="Expected close" name="closeDate" type="date" required /><SelectField label="Assigned user" name="owner" options={['Sandya Kandi', 'Priya Sharma', 'Arjun Mehta', 'Rahul Menon']} /></div></section><div className="form-footer"><Link to="/opportunities" className="button button-secondary">Cancel</Link><Button type="submit" icon={<Check size={16} />}>Save opportunity</Button></div></form></>
  return <><PageHeader eyebrow={isCustomer ? 'CUSTOMER MANAGEMENT' : 'LEAD MANAGEMENT'} title={`${editing ? 'Edit' : 'Add'} ${kind}`} description="Enter the details below. You can update this record at any time." actions={<Link to={isCustomer ? '/customers' : '/leads'} className="button button-quiet"><ArrowLeft size={15} />Back</Link>} /><form className="form-layout" onSubmit={submit}><section className="panel form-panel"><div className="form-section-title"><span>01</span><div><h2>{isCustomer ? 'Personal information' : 'Contact information'}</h2><p>Basic details to identify and reach this {kind}.</p></div></div><div className="form-grid"><Field label="First name" name="first" required placeholder="e.g. Ananya" defaultValue={existing?.name.split(' ')[0]} /><Field label="Last name" name="last" required placeholder="e.g. Rao" defaultValue={existing?.name.split(' ').slice(1).join(' ')} /><Field label="Email address" name="email" type="email" required placeholder="name@company.com" defaultValue={existing?.email} /><Field label="Phone number" name="phone" placeholder="+91 98765 43210" defaultValue={existing?.phone} /></div></section><section className="panel form-panel"><div className="form-section-title"><span>02</span><div><h2>{isCustomer ? 'Company information' : 'Qualification'}</h2><p>{isCustomer ? 'Where this relationship takes place.' : 'How this prospect found you and where they stand.'}</p></div></div><div className="form-grid"><Field label="Company name" name="company" required placeholder="Company name" defaultValue={existing?.company} />{isCustomer ? <><Field label="Industry" name="industry" placeholder="e.g. Technology" /><Field label="City" name="city" placeholder="City" defaultValue={existingCustomer?.city} /><Field label="State" name="state" placeholder="State" /><Field label="Country" name="country" placeholder="Country" /><Field label="Postal code" name="postal" placeholder="Postal code" /></> : <><SelectField label="Lead source" name="source" options={['Website', 'Referral', 'Advertisement', 'Social Media', 'Campaign', 'Other']} defaultValue={existingLead?.source} /><SelectField label="Status" name="status" options={['New', 'Contacted', 'Qualified', 'Unqualified', 'Converted', 'Lost']} defaultValue={existingLead?.status} /><SelectField label="Rating" name="rating" options={['Hot', 'Warm', 'Cold']} defaultValue={existingLead?.rating} /><Field label="Description" name="description" placeholder="Add context about this lead" /></>}</div></section><section className="panel form-panel"><div className="form-section-title"><span>03</span><div><h2>Assignment</h2><p>Choose an owner and set the current status.</p></div></div><div className="form-grid"><SelectField label="Assigned user" name="owner" options={['Sandya Kandi', 'Priya Sharma', 'Arjun Mehta', 'Rahul Menon']} defaultValue={existing?.owner} />{isCustomer && <SelectField label="Status" name="status" options={['Active', 'Prospect', 'Inactive']} defaultValue={existingCustomer?.status} />}</div></section>{error && <p className="form-error" role="alert">{error}</p>}<div className="form-footer"><Link to={isCustomer ? '/customers' : '/leads'} className="button button-secondary">Cancel</Link><Button type="submit" icon={<Check size={16} />}>Save {kind}</Button></div></form></>
}
function Field({ label, name, type = 'text', required = false, placeholder = '', defaultValue }: { label: string; name: string; type?: string; required?: boolean; placeholder?: string; defaultValue?: string }) { return <label className="form-field"><span>{label}{required && <i> *</i>}</span><input name={name} type={type} required={required} placeholder={placeholder} defaultValue={defaultValue} /></label> }
function SelectField({ label, name, options, defaultValue }: { label: string; name: string; options: string[]; defaultValue?: string }) { return <label className="form-field"><span>{label}</span><select name={name} defaultValue={defaultValue}>{options.map((option) => <option key={option}>{option}</option>)}</select></label> }

function OpportunitiesPage() {
  const { opportunities } = useCRM(); const [view, setView] = useState<'table' | 'pipeline'>('table'); const [search, setSearch] = useState(''); const shown = opportunities.filter((item) => `${item.name} ${item.customer} ${item.owner}`.toLowerCase().includes(search.toLowerCase())); const stages = ['Prospecting', 'Qualification', 'Proposal', 'Negotiation', 'Closed Won', 'Closed Lost']
  return <><PageHeader title="Opportunities" description="Track deals from first conversation to close." actions={<><div className="view-toggle"><button className={view === 'table' ? 'selected' : ''} onClick={() => setView('table')} aria-label="Table view"><ListFilter size={16} /></button><button className={view === 'pipeline' ? 'selected' : ''} onClick={() => setView('pipeline')} aria-label="Pipeline view"><Kanban size={16} /></button></div><Link className="button button-primary" to="/opportunities/new"><Plus size={16} />Add opportunity</Link></>} />{view === 'table' ? <section className="panel table-panel"><div className="table-toolbar"><SearchInput value={search} onChange={setSearch} placeholder="Search opportunities..." /><span className="toolbar-spacer" /><span className="result-count">{shown.length} opportunities</span></div><TableWrap><thead><tr><th>Opportunity</th><th>Customer</th><th>Amount</th><th>Stage</th><th>Probability</th><th>Expected close</th><th>Assigned to</th><th>Status</th></tr></thead><tbody>{shown.map((item) => <tr key={item.id}><td><Link className="table-link" to={`/opportunities/${item.id}`}>{item.name}</Link></td><td>{item.customer}</td><td className="amount">₹{(item.amount / 100000).toFixed(1)}L</td><td>{item.stage}</td><td><span className="probability"><i style={{ width: `${item.probability}%` }} />{item.probability}%</span></td><td>{item.closeDate}</td><td>{item.owner}</td><td><StatusBadge status={item.stage.startsWith('Closed') ? item.stage.slice(7) : 'Open'} /></td></tr>)}</tbody></TableWrap><Pagination count={shown.length} label="opportunities" /></section> : <div className="pipeline-board">{stages.map((stage) => { const cards = shown.filter((item) => item.stage === stage); return <section className="pipeline-column" key={stage}><div className="pipeline-title"><span>{stage}</span><i>{cards.length}</i></div>{cards.map((item) => <Link className="opportunity-card" to={`/opportunities/${item.id}`} key={item.id}><strong>{item.name}</strong><span>{item.customer}</span><div><b>₹{(item.amount / 100000).toFixed(1)}L</b><small>{item.probability}%</small></div><div className="opportunity-card-foot"><span><Avatar name={item.owner} small />{item.owner.split(' ')[0]}</span><small>{item.closeDate}</small></div></Link>)}<button className="add-card"><Plus size={14} />Add opportunity</button></section> })}</div>}</>
}

function RecordDetails({ kind }: { kind: 'customer' | 'lead' | 'opportunity' }) {
  const { id = '' } = useParams(); const { customers, leads, opportunities, activities, convertLead, updateOpportunity } = useCRM(); const [confirm, setConfirm] = useState(false); const [toast, setToast] = useState(''); const [tab, setTab] = useState('Overview')
  const record = kind === 'customer' ? customers.find((item) => item.id === id) : kind === 'lead' ? leads.find((item) => item.id === id) : opportunities.find((item) => item.id === id)
  if (!record) return <><PageHeader title="Record not found" description="This record may have been removed or is unavailable." /><Link className="button button-secondary" to={`/${kind === 'opportunity' ? 'opportunities' : `${kind}s`}`}><ArrowLeft size={15} />Back to {kind}s</Link></>
  const name = kind === 'opportunity' ? (record as Opportunity).name : record.name; const company = kind === 'opportunity' ? (record as Opportunity).customer : 'company' in record ? record.company : ''; const person = record as Customer | Lead
  return <><PageHeader eyebrow={`${kind.toUpperCase()} PROFILE`} title={name} description={company} actions={<><Link to={kind === 'opportunity' ? '/opportunities' : `/${kind}s`} className="button button-quiet"><ArrowLeft size={15} />Back</Link>{kind !== 'opportunity' && <Link className="button button-secondary" to={`/${kind}s/${id}/edit`}>Edit details</Link>}{kind === 'lead' && <Button onClick={() => setConfirm(true)} icon={<ArrowRight size={15} />}>Convert lead</Button>}{kind === 'opportunity' && <><Button variant="secondary" onClick={() => { updateOpportunity(id, 'Closed Won'); setToast('Opportunity marked as Won.') }}><Check size={15} />Mark won</Button><Button variant="secondary" onClick={() => { updateOpportunity(id, 'Closed Lost'); setToast('Opportunity marked as Lost.') }}>Mark lost</Button></>}</>} /><div className="detail-tabs">{['Overview', 'Activities', 'Follow-ups', 'Notes'].map((item) => <button onClick={() => setTab(item)} className={tab === item ? 'active' : ''} key={item}>{item}</button>)}</div><div className="detail-layout"><section className="panel detail-main"><div className="detail-profile"><Avatar name={name} /><div><h2>{name}</h2><span>{company || ('source' in record ? record.source : 'Opportunity')}</span></div><StatusBadge status={kind === 'opportunity' ? (record as Opportunity).stage : person.status} /></div><div className="detail-fields">{kind === 'opportunity' ? <><DetailField label="Customer" value={company} /><DetailField label="Amount" value={`₹${((record as Opportunity).amount / 100000).toFixed(1)}L`} /><DetailField label="Probability" value={`${(record as Opportunity).probability}%`} /><DetailField label="Expected close" value={(record as Opportunity).closeDate} /><DetailField label="Assigned to" value={(record as Opportunity).owner} /><DetailField label="Stage" value={(record as Opportunity).stage} /></> : <><DetailField label="Email" value={person.email} /><DetailField label="Phone" value={person.phone} /><DetailField label="Company" value={company} /><DetailField label="Assigned to" value={person.owner} /><DetailField label="Created" value={person.created} />{'city' in person && <DetailField label="City" value={person.city} />}{'source' in person && <DetailField label="Source" value={person.source} />}{'rating' in person && <DetailField label="Rating" value={person.rating} />}</>}</div></section><section className="panel detail-side"><div className="panel-heading"><div><h2>{tab === 'Overview' ? 'Recent activity' : tab}</h2><p>Latest updates for this {kind}</p></div><Button variant="quiet" icon={<Plus size={15} />}>Add</Button></div><div className="detail-timeline">{activities.slice(0, 4).map((item) => <div className="timeline-row" key={item.id}><span className="timeline-dot" /><div><strong>{item.subject}</strong><p>{item.description}</p><small>{item.user} · {item.time}</small></div></div>)}</div></section></div>{confirm && <ConfirmDialog title="Convert this lead?" message="This will create a customer record and update the lead status to Converted." onCancel={() => setConfirm(false)} onConfirm={() => { convertLead(id); setConfirm(false); setToast('Lead converted successfully.') }} />}<Toast message={toast} onClose={() => setToast('')} /></>
}
function DetailField({ label, value }: { label: string; value: string | number }) { return <div><span>{label}</span><strong>{value}</strong></div> }
function ConfirmDialog({ title, message, onCancel, onConfirm }: { title: string; message: string; onCancel: () => void; onConfirm: () => void }) { return <div className="modal-backdrop" role="presentation" onMouseDown={(event) => event.target === event.currentTarget && onCancel()}><section className="modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><button className="modal-close" onClick={onCancel} aria-label="Close dialog"><X size={18} /></button><span className="modal-icon"><ArrowRight size={19} /></span><h2 id="dialog-title">{title}</h2><p>{message}</p><div className="modal-actions"><Button variant="secondary" onClick={onCancel}>Cancel</Button><Button onClick={onConfirm}>Confirm</Button></div></section></div> }

function FollowUpsPage() {
  const { followUps, completeFollowUp, addFollowUp } = useCRM(); const [status, setStatus] = useState('All'); const [search, setSearch] = useState(''); const [open, setOpen] = useState(false); const [toast, setToast] = useState(''); const shown = followUps.filter((item) => `${item.subject} ${item.related} ${item.owner}`.toLowerCase().includes(search.toLowerCase()) && (status === 'All' || item.status === status))
  function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const form = new FormData(event.currentTarget); addFollowUp({ id: `FOL-${Date.now().toString().slice(-5)}`, subject: String(form.get('subject')), related: String(form.get('related')), type: String(form.get('type')), date: String(form.get('date')), time: String(form.get('time')), owner: String(form.get('owner')), status: 'Pending' }); setOpen(false); setToast('Follow-up created successfully.') }
  return <><PageHeader title="Follow-ups" description="Keep every conversation moving forward." actions={<Button onClick={() => setOpen(true)} icon={<Plus size={16} />}>Add follow-up</Button>} /><div className="summary-strip"><div><span>Due today</span><strong>06</strong></div><div><span>Overdue</span><strong className="text-red">02</strong></div><div><span>Completed this week</span><strong>24</strong></div><div><span>Upcoming</span><strong>18</strong></div></div><section className="panel table-panel"><div className="table-toolbar"><SearchInput value={search} onChange={setSearch} placeholder="Search follow-ups..." /><select className="filter-select" value={status} onChange={(event) => setStatus(event.target.value)}>{['All', 'Pending', 'Overdue', 'Completed', 'Cancelled'].map((item) => <option key={item}>{item}</option>)}</select><span className="toolbar-spacer" /><button className="button button-secondary filter-button"><CalendarClock size={15} />Calendar</button></div><TableWrap><thead><tr><th>Follow-up</th><th>Related to</th><th>Type</th><th>Date &amp; time</th><th>Assigned to</th><th>Status</th><th>Action</th></tr></thead><tbody>{shown.map((item) => <tr key={item.id}><td><strong className="row-strong">{item.subject}</strong></td><td>{item.related}</td><td><span className="type-pill">{item.type}</span></td><td>{item.date} <span className="muted">{item.time}</span></td><td>{item.owner}</td><td><StatusBadge status={item.status} /></td><td>{item.status !== 'Completed' && <button className="row-action" onClick={() => completeFollowUp(item.id)} aria-label="Mark completed"><Check size={16} /></button>}</td></tr>)}</tbody></TableWrap>{shown.length === 0 && <EmptyState title="No follow-ups found" text="Adjust the filters or create a follow-up." />}<Pagination count={shown.length} label="follow-ups" /></section>{open && <div className="modal-backdrop"><form className="modal form-modal" onSubmit={submit}><button type="button" className="modal-close" onClick={() => setOpen(false)} aria-label="Close"><X size={18} /></button><h2>Add follow-up</h2><p>Schedule the next customer touchpoint.</p><div className="modal-fields"><Field label="Subject" name="subject" required placeholder="e.g. Product walkthrough" /><Field label="Related to" name="related" required placeholder="Customer, lead, or opportunity" /><SelectField label="Type" name="type" options={['Call', 'Email', 'Meeting', 'Visit', 'Task']} /><Field label="Date" name="date" type="date" required /><Field label="Time" name="time" type="time" required /><SelectField label="Assigned user" name="owner" options={['Sandya Kandi', 'Priya Sharma', 'Arjun Mehta', 'Rahul Menon']} /></div><div className="modal-actions"><Button variant="secondary" onClick={() => setOpen(false)}>Cancel</Button><Button type="submit">Save follow-up</Button></div></form></div>}<Toast message={toast} onClose={() => setToast('')} /></>
}

function ActivitiesPage() {
  const { activities, addActivity } = useCRM(); const [open, setOpen] = useState(false); const [toast, setToast] = useState('')
  function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const form = new FormData(event.currentTarget); addActivity({ id: `ACT-${Date.now()}`, type: String(form.get('type')), subject: String(form.get('subject')), description: String(form.get('description')), user: 'Sandya Kandi', related: String(form.get('related') || 'General'), time: 'Just now' }); setOpen(false); setToast('Activity added successfully.') }
  return <><PageHeader title="Activities" description="A shared timeline of conversations and updates." actions={<Button onClick={() => setOpen(true)} icon={<Plus size={16} />}>Add activity</Button>} /><section className="panel activity-page-panel"><div className="timeline-date">TODAY <span>OCTOBER 8, 2026</span></div>{activities.map((item) => <article className="full-activity" key={item.id}><span className={`activity-symbol activity-${item.type.toLowerCase()}`}>{item.type === 'Email' ? <Mail size={16} /> : item.type === 'Meeting' ? <Users size={16} /> : item.type === 'Call' ? '↗' : <MessageSquareText size={16} />}</span><div className="full-activity-main"><div><strong>{item.subject}</strong><span className="activity-type-tag">{item.type}</span></div><p>{item.description}</p><span className="activity-related">Related to <strong>{item.related}</strong></span></div><div className="full-activity-meta"><Avatar name={item.user} small /><span>{item.user}</span><small>{item.time}</small></div></article>)}</section>{open && <div className="modal-backdrop"><form className="modal form-modal" onSubmit={submit}><button type="button" className="modal-close" onClick={() => setOpen(false)} aria-label="Close"><X size={18} /></button><h2>Add activity</h2><p>Log a conversation or update to the timeline.</p><div className="modal-fields"><SelectField label="Activity type" name="type" options={['Call', 'Email', 'Meeting', 'Task', 'Note']} /><Field label="Subject" name="subject" required placeholder="What happened?" /><Field label="Related to" name="related" placeholder="Customer, lead, or opportunity" /><Field label="Description" name="description" placeholder="Add a few details" /></div><div className="modal-actions"><Button variant="secondary" onClick={() => setOpen(false)}>Cancel</Button><Button type="submit">Save activity</Button></div></form></div>}<Toast message={toast} onClose={() => setToast('')} /></>
}

