function UsersPage() {
  const { users } = useCRM(); const [rows, setRows] = useState(users); const [search, setSearch] = useState(''); const [open, setOpen] = useState(false); const shown = rows.filter((item) => `${item.name} ${item.email} ${item.role}`.toLowerCase().includes(search.toLowerCase()))
  function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const form = new FormData(event.currentTarget); setRows((items) => [{ name: String(form.get('name')), email: String(form.get('email')), role: String(form.get('role')), status: 'Active', created: todayISO() }, ...items]); setOpen(false) }
  return <><PageHeader title="Users" description="Manage workspace access and team roles." actions={<Button onClick={() => setOpen(true)} icon={<Plus size={16} />}>Add user</Button>} /><section className="panel table-panel"><div className="table-toolbar"><SearchInput value={search} onChange={setSearch} placeholder="Search users..." /><select className="filter-select"><option>All roles</option><option>Admin</option><option>Manager</option><option>Sales Executive</option></select><span className="toolbar-spacer" /><span className="result-count">{shown.length} users</span></div><TableWrap><thead><tr><th>User</th><th>Email</th><th>Role</th><th>Status</th><th>Created date</th><th /></tr></thead><tbody>{shown.map((item) => <tr key={item.email}><td><span className="person-cell"><Avatar name={item.name} small /><strong>{item.name}</strong></span></td><td>{item.email}</td><td>{item.role}</td><td><StatusBadge status={item.status} /></td><td>{item.created}</td><td><button className="row-action" aria-label="User actions"><MoreHorizontal size={17} /></button></td></tr>)}</tbody></TableWrap><Pagination count={shown.length} label="users" /></section>{open && <div className="modal-backdrop"><form className="modal form-modal" onSubmit={submit}><button type="button" className="modal-close" onClick={() => setOpen(false)} aria-label="Close"><X size={18} /></button><h2>Add user</h2><p>Create a workspace user and assign a role.</p><div className="modal-fields"><Field label="Full name" name="name" required placeholder="Name" /><Field label="Email" name="email" type="email" required placeholder="name@company.com" /><SelectField label="Role" name="role" options={['Admin', 'Manager', 'Sales Executive']} /></div><div className="modal-actions"><Button variant="secondary" onClick={() => setOpen(false)}>Cancel</Button><Button type="submit">Add user</Button></div></form></div>}</>
}
