function SettingsPage() {
  const [saved, setSaved] = useState(false)
  return <><PageHeader title="Settings" description="Personalize your workspace and account preferences." /><div className="settings-layout"><section className="panel settings-panel"><div className="settings-section"><span className="settings-icon"><ContactRound size={18} /></span><div className="settings-body"><h2>Profile information</h2><p>Update your personal details.</p><div className="form-grid"><Field label="Full name" name="settings-name" placeholder="Sandya Kandi" /><Field label="Email address" name="settings-email" type="email" placeholder="sandya@acxiom.com" /><Field label="Phone number" name="settings-phone" placeholder="+91 98765 43210" /><Field label="Job title" name="settings-job" placeholder="Sales Executive" /></div></div></div><div className="settings-section"><span className="settings-icon"><Settings size={18} /></span><div className="settings-body"><h2>Preferences</h2><p>Choose how AcxiomCRM works for you.</p><label className="setting-line"><span><strong>Product updates</strong><small>Receive occasional updates about new features.</small></span><input type="checkbox" defaultChecked /></label><label className="setting-line"><span><strong>Email notifications</strong><small>Get notified about tasks and follow-ups.</small></span><input type="checkbox" defaultChecked /></label><label className="form-field"><span>Appearance</span><select><option>Light</option><option>System</option></select></label></div></div><div className="settings-section"><span className="settings-icon"><ShieldCheck size={18} /></span><div className="settings-body"><h2>Security</h2><p>Keep your account protected.</p><Button variant="secondary">Change password</Button></div></div><div className="settings-footer"><span>{saved ? 'Your settings have been saved.' : ''}</span><Button onClick={() => setSaved(true)}>Save changes</Button></div></section><aside className="settings-aside"><div className="settings-profile"><Avatar name="Sandya Kandi" /><h3>Sandya Kandi</h3><p>Sales Executive</p><span>Acxiom Group</span></div><div className="panel settings-help"><strong>Need a hand?</strong><p>Visit our help center for guidance with your workspace.</p><button className="text-link">Visit help center <ArrowRight size={14} /></button></div></aside></div></>
}

function AuthPage({ mode }: { mode: 'login' | 'register' }) {
  const isRegister = mode === 'register'; const navigate = useNavigate(); const [error, setError] = useState('')
  function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const form = new FormData(event.currentTarget); if (isRegister && form.get('password') !== form.get('confirm')) { setError('Passwords do not match.'); return } navigate('/dashboard') }
  return <div className="auth-screen"><div className="auth-brand"><Link className="brand" to="/login"><span className="brand-mark"><Command size={18} /></span><span className="brand-name">acxiom<span>crm</span></span></Link><span className="auth-product">CUSTOMER RELATIONSHIP MANAGEMENT</span></div><div className="auth-layout"><section className="auth-promo"><div className="promo-orbit orbit-one" /><div className="promo-orbit orbit-two" /><span className="eyebrow">RELATIONSHIPS, IN FOCUS</span><h1>Make every<br />connection <em>count.</em></h1><p>One considered space to understand your customers, build momentum, and grow together.</p><div className="promo-stat"><span className="promo-stat-icon"><Target size={19} /></span><div><strong>2,400+</strong><span>customer relationships managed</span></div></div><span className="promo-footer">BUILT FOR TEAMS THAT PUT PEOPLE FIRST</span></section><section className="auth-form-area"><div className="auth-form-wrap"><span className="auth-kicker">{isRegister ? 'GET STARTED' : 'WELCOME BACK'}</span><h2>{isRegister ? 'Create your account' : 'Sign in to AcxiomCRM'}</h2><p>{isRegister ? 'Set up your workspace in just a moment.' : 'Enter your details to access your workspace.'}</p><form onSubmit={submit}>{isRegister && <Field label="Full name" name="name" required placeholder="Your full name" />}<Field label="Work email" name="email" type="email" required placeholder="you@company.com" /><Field label="Password" name="password" type="password" required placeholder="Enter your password" />{isRegister ? <Field label="Confirm password" name="confirm" type="password" required placeholder="Confirm your password" /> : <div className="auth-options"><label><input type="checkbox" />Remember me</label><button type="button">Forgot password?</button></div>}{error && <div className="form-error">{error}</div>}<Button type="submit" className="auth-submit">{isRegister ? 'Create account' : 'Sign in'}<ArrowRight size={16} /></Button></form><div className="auth-switch">{isRegister ? 'Already have an account?' : 'New to AcxiomCRM?'} <Link to={isRegister ? '/login' : '/register'}>{isRegister ? 'Sign in' : 'Create an account'}</Link></div><div className="auth-demo-note"><ShieldCheck size={15} />Demo experience · No real authentication</div></div></section></div><footer className="auth-footer"><span>© 2025 Acxiom Group</span><span>Privacy <i>·</i> Terms <i>·</i> Help</span></footer></div>
}
function NotFound() { return <div className="not-found"><span>404</span><h1>We couldn’t find that page.</h1><p>The page may have moved or the link may be out of date.</p><Link className="button button-primary" to="/dashboard"><ArrowLeft size={15} />Back to dashboard</Link></div> }